<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { request, downloadCsv } from './api'
import { date, fmt, label, tone } from './labels'
import type { BusinessRecord, Column, SessionUser, Workspace } from './types'
import type { DecisionContext, DecisionDashboard, DecisionFutures, DecisionMetric, DecisionSource, FutureObservation, PolicyEvent } from './decisionTypes'
import Icon from './Icon.vue'
import RecordTable from './RecordTable.vue'
const props=defineProps<{projectId:string;region:string;page:string;user:SessionUser;decisionRecords:BusinessRecord[];workspace:Workspace}>()
const emit=defineEmits<{record:[context:Record<string,unknown>];enroll:[decision:BusinessRecord];navigate:[page:string];task:[task:BusinessRecord]}>()
const dashboard=ref<DecisionDashboard|null>(null),futures=ref<DecisionFutures|null>(null)
const capabilities=ref<{items:DecisionSource[];soil_definition_notice?:string}|null>(null),policyEvents=ref<{status:string;items:PolicyEvent[];sources:DecisionSource[];notice?:string}|null>(null)
const loading=ref(false),loadingFutures=ref(false),error=ref(''),futureError=ref(''),coverageError=ref('')
const ticker=ref(''),range=ref(60),chartMode=ref<'candles'|'settle'>('candles')
let alive=true,loadSequence=0,futureSequence=0
const productMarket=computed(()=>dashboard.value?.market.cards.find(c=>c.is_product_contract)||dashboard.value?.market.cards.find(c=>c.ticker===dashboard.value?.market.default_ticker))
const supplyMetric=(id:string)=>dashboard.value?.supply_demand.metrics.find(m=>m.id===id)
function metricValue(metric?:DecisionMetric){if(metric?.value==null)return {value:'未提供',unit:''};if(metric.unit==='比例')return {value:fmt(metric.value*100,4),unit:'%'};if(metric.unit==='吨'&&Math.abs(metric.value)>=10000)return{value:fmt(metric.value/10000),unit:'万吨'};return{value:fmt(metric.value),unit:metric.unit}}
const mainSupply=computed(()=>['production','domestic_consumption','imports_my','exports_my','domestic_share','export_share'].map(id=>supplyMetric(id)).filter((m):m is DecisionMetric=>!!m))
const context=computed<DecisionContext>(()=>dashboard.value?.source_context||{})
const currentRegion=computed(()=>currentWeather.value?.region_name||props.region||dashboard.value?.project.region||'项目地区待确认')
const selectedRegion=ref('231200'),policyCategory=ref('all'),policyCountry=ref('all'),expandedPolicy=ref('')
const regionObservations=computed(()=>dashboard.value?.agri_risk.regional_observations||[])
const currentWeather=computed(()=>regionObservations.value.find(r=>r.region_code===selectedRegion.value)||dashboard.value?.agri_risk.latest_observation)
const riskItems=computed(()=>(dashboard.value?.agri_risk.all_assessments||dashboard.value?.agri_risk.assessments||[]).filter(r=>r.region_code===(currentWeather.value?.region_code||selectedRegion.value)))
const highestRisk=computed(()=>riskItems.value.length?riskItems.value.reduce((a,b)=>a.probability>=b.probability?a:b):undefined)
const policyItems=computed(()=>(policyEvents.value?.items||dashboard.value?.policy.items||[]).filter(p=>(policyCategory.value==='all'||p.category===policyCategory.value)&&(policyCountry.value==='all'||p.country_code===policyCountry.value)))
const policyCountries=computed(()=>[...new Set((policyEvents.value?.items||dashboard.value?.policy.items||[]).map(p=>p.country_code).filter((c):c is string=>!!c))])
const onlyMyTasks=ref(true)
const openTasks=computed(()=>props.workspace.tasks.filter(t=>!['done','resolved','closed'].includes(t.status)))
const taskPriority=(task:BusinessRecord)=>['unknown','missing','needs_review','invalidated'].includes(task.status)?0:1
const pendingTasks=computed(()=>openTasks.value.filter(t=>!onlyMyTasks.value||t.assignee_role===props.user.role).slice().sort((a,b)=>taskPriority(a)-taskPriority(b)||String(a.created_at||'').localeCompare(String(b.created_at||''))))
const shortcuts=computed(()=>[
 {page:'applications',label:'投保办理',icon:'policy',note:'接收申请、补件与核保',count:openTasks.value.filter(t=>t.source_type==='applications').length},
 {page:'experiments',label:'业务研究',icon:'research',note:'配置数据、因子与实验'},
 {page:'arrangements',label:'再保与对冲',icon:'risk',note:'风险安排、审批与执行',count:openTasks.value.filter(t=>['plans','executions','allocations','reinsurance_allocations'].includes(String(t.source_type))).length},
 {page:'fixings',label:'核赔与支付',icon:'settlement',note:'合同采价、核赔与到账',count:openTasks.value.filter(t=>['fixings','claims','payments'].includes(String(t.source_type))).length},
])
const latestDecisions=computed(()=>props.decisionRecords.slice(-3).reverse())
function safeUrl(value?:string){try{const url=new URL(value||'');return ['https:','http:'].includes(url.protocol)?url.href:undefined}catch{return undefined}}
function sourceState(value?:string){return value==='available'?'当前版本':label(value)}
async function loadFutures(selected?:string){const seq=++futureSequence;loadingFutures.value=true;futureError.value='';futures.value=null;try{const result=await request<DecisionFutures>(`/decision/futures?project_id=${encodeURIComponent(props.projectId)}${selected?`&ticker=${encodeURIComponent(selected)}`:''}`);if(!alive||seq!==futureSequence)return;futures.value=result;ticker.value=result.ticker}catch(e){if(alive&&seq===futureSequence)futureError.value=(e as Error).message}finally{if(alive&&seq===futureSequence)loadingFutures.value=false}}
async function load(){const seq=++loadSequence;loading.value=true;error.value='';coverageError.value='';const results=await Promise.allSettled([request<DecisionDashboard>(`/decision/dashboard?project_id=${encodeURIComponent(props.projectId)}`),request<{items:DecisionSource[];soil_definition_notice?:string}>(`/decision/capabilities?project_id=${encodeURIComponent(props.projectId)}`),request<{status:string;items:PolicyEvent[];sources:DecisionSource[];notice?:string}>(`/decision/policy-events?project_id=${encodeURIComponent(props.projectId)}`),loadFutures()]);if(!alive||seq!==loadSequence)return;if(results[0].status==='fulfilled')dashboard.value=results[0].value;else{dashboard.value=null;error.value=(results[0].reason as Error).message}if(results[1].status==='fulfilled')capabilities.value=results[1].value;else coverageError.value=(results[1].reason as Error).message;if(results[2].status==='fulfilled')policyEvents.value=results[2].value;else coverageError.value=(results[2].reason as Error).message;loading.value=false}
function record(){
 if(!dashboard.value)return
 const weather=currentWeather.value,risks=riskItems.value
 emit('record',{region:currentRegion.value,source_context:{
  ...context.value,
  region_code:weather?.region_code||null,
  environment_observation_id:weather?.id||null,
  environment_observation_date:weather?.observation_date||null,
  environment_version:weather?.release_id||weather?.seed_batch||null,
  risk_model_version:risks[0]?.model_version||null,
  risk_as_of:risks[0]?.as_of||null,
  risk_assessments:risks.map(risk=>({id:risk.id,region_code:risk.region_code,model_version:risk.model_version,as_of:risk.as_of,valid_until:risk.valid_until})),
  source_status:{...Object.fromEntries(dashboard.value.coverage.map(c=>[c.id,c.status])),environment:weather?'available':'not_ready',agri_disaster_risk:risks.length?'available':'not_ready'},
 }})
}
watch(()=>props.page,page=>{if(page==='decision'&&dashboard.value&&futures.value?.ticker!==dashboard.value.market.default_ticker)loadFutures(dashboard.value.market.default_ticker)})
onMounted(load);onBeforeUnmount(()=>{alive=false;loadSequence++;futureSequence++})
const history=computed(()=>futures.value?.history.slice(-range.value)||[])
const validPrice=(row:FutureObservation)=>[row.low_price,row.high_price,row.open_price,row.close_price,row.settle_price].filter((x):x is number=>x!=null&&Number.isFinite(x))
const isProductContract=computed(()=>futures.value?.ticker===dashboard.value?.product.contract)
const priceBounds=computed(()=>{const values=history.value.flatMap(validPrice);if(isProductContract.value&&dashboard.value?.product.guarantee_price!=null)values.push(dashboard.value.product.guarantee_price);const min=values.length?Math.min(...values):0,max=values.length?Math.max(...values):1,pad=(max-min)*.1||1;return{min:min-pad,max:max+pad}})
const x=(i:number)=>58+i/Math.max(1,history.value.length-1)*730
const y=(value:number)=>25+(1-(value-priceBounds.value.min)/(priceBounds.value.max-priceBounds.value.min))*185
const candleWidth=computed(()=>Math.min(9,550/Math.max(history.value.length,1)))
const hasOHLC=computed(()=>history.value.some(r=>r.open_price!=null&&r.high_price!=null&&r.low_price!=null&&r.close_price!=null))
const hasPrice=computed(()=>history.value.some(r=>validPrice(r).length>0))
const maxVolume=computed(()=>Math.max(1,...history.value.map(r=>r.volume||0)))
const volumeY=(value:number)=>300-value/maxVolume.value*55
const settlePath=computed(()=>{let d='',gap=true;history.value.forEach((r,i)=>{if(r.settle_price==null){gap=true;return}d+=`${gap?'M':'L'}${x(i)},${y(r.settle_price)} `;gap=false});return d})
const candles=computed(()=>history.value.map((row,i)=>({row,i})).filter(c=>c.row.open_price!=null&&c.row.high_price!=null&&c.row.low_price!=null&&c.row.close_price!=null))
const futureColumns:Column[]=[{key:'date',label:'交易日'},{key:'open_price',label:'开盘价',format:'number'},{key:'high_price',label:'最高价',format:'number'},{key:'low_price',label:'最低价',format:'number'},{key:'close_price',label:'收盘价',format:'number'},{key:'settle_price',label:'结算价',format:'number'},{key:'settle_change_ratio',label:'结算价变动',format:'percent'},{key:'volume',label:'成交量（手）',format:'number'},{key:'open_interest',label:'持仓量（手）',format:'number'}]
const futureRecords=computed(()=>history.value.slice().reverse().map(r=>({...r,id:r.date,version:1,status:r.quality_flag||''})))
function exportFutures(records:BusinessRecord[]){downloadCsv(`${ticker.value}_期货行情`,futureColumns.map(c=>c.key==='settle_change_ratio'?{...c,label:'结算价变动（比例原值）'}:c),records)}
</script>
<template>
<div v-if="error" class="gg-error" role="alert"><Icon name="warning" :size="18"/><span>{{ error }}</span><button class="gg-text-btn" @click="load">重新加载</button></div>
<div v-if="loading&&!dashboard" class="gg-loading"><span class="gg-spinner"/>正在核对行情、供需与项目资料覆盖…</div>
<template v-if="dashboard">
 <div class="gg-decision-context"><span><Icon name="building" :size="16"/>{{ currentRegion }}</span><span>产品指定合约 <b>{{ dashboard.product.contract.toUpperCase() }}</b></span><span>资料参考，不直接改变保险条款</span><button class="gg-text-btn" :disabled="loading" @click="load"><Icon name="refresh" :size="14"/>刷新资料</button><button v-if="page==='decision'&&user.role==='operator'" class="gg-btn gg-btn-primary" @click="record">记录业务判断<Icon name="arrow" :size="15"/></button></div>
 <template v-if="page==='decision'">
  <div class="gg-decision-cards">
   <article><header><span class="gg-decision-icon"><Icon name="grain" :size="21"/></span><span>供需背景</span><span class="gg-badge" :class="`gg-${tone(dashboard.supply_demand.status)}`">{{ sourceState(dashboard.supply_demand.status) }}</span></header><strong>{{ metricValue(supplyMetric('production')).value }}<small>{{ metricValue(supplyMetric('production')).unit }}</small></strong><h3>中国玉米产量 · {{ dashboard.supply_demand.marketing_year }}</h3><p>中国玉米供需 · {{ label(dashboard.supply_demand.statistic_status) }}</p><footer><span>发布 {{ date(dashboard.supply_demand.published_at).slice(0,10) }}</span><a :href="safeUrl(dashboard.supply_demand.source_uri)" target="_blank" rel="noopener noreferrer">原文<Icon name="external" :size="12"/></a></footer></article>
   <article><header><span class="gg-decision-icon gg-icon-blue"><Icon name="research" :size="21"/></span><span>期货行情</span><span class="gg-badge gg-info">日行情</span></header><strong>{{ fmt(productMarket?.settle_price) }}<small>元/吨</small></strong><h3>{{ dashboard.product.contract.toUpperCase() }} · 指定合约结算价</h3><p :class="productMarket?.settle_change!=null&&productMarket.settle_change<0?'gg-market-down':'gg-market-up'">{{ productMarket?.settle_change!=null&&productMarket.settle_change>0?'+':'' }}{{ fmt(productMarket?.settle_change) }} 元/吨 · {{ productMarket?.settle_change_ratio==null?'—':`${fmt(productMarket.settle_change_ratio*100)}%` }}</p><footer><span>交易日 {{ productMarket?.as_of||'未覆盖' }}</span><button class="gg-text-btn" @click="emit('navigate','futures')">看板<Icon name="arrow" :size="12"/></button></footer></article>
   <article><header><span class="gg-decision-icon gg-icon-green"><Icon name="risk" :size="21"/></span><span>区域农情</span><span class="gg-badge" :class="`gg-${tone(highestRisk?.risk_level)}`">{{ label(highestRisk?.risk_level) }}</span></header><strong class="gg-decision-text">{{ fmt(currentWeather?.temperature_c) }}<small>℃ · 日均气温</small></strong><h3>土壤水分饱和度 {{ currentWeather?fmt(currentWeather.soil_saturation*100,1):'—' }}%</h3><p>{{ highestRisk?.hazard_name||'区域风险研判' }} · 未来7日概率 {{ highestRisk?fmt(highestRisk.probability*100,1):'—' }}%</p><footer><span>{{ currentWeather?.region_name }} · {{ currentWeather?.observation_date }}</span><button class="gg-text-btn" @click="emit('navigate','agri-risk')">农情研判<Icon name="arrow" :size="12"/></button></footer></article>
   <article><header><span class="gg-decision-icon gg-icon-gold"><Icon name="file" :size="21"/></span><span>政策动态</span><span class="gg-badge gg-info">{{ (policyEvents?.items||dashboard.policy.items).length }} 条动态</span></header><strong class="gg-decision-text">{{ (policyEvents?.items||dashboard.policy.items)[0]?.title||'政策与市场背景' }}</strong><h3>农业支持 · 保险服务 · 国际贸易</h3><p>{{ (policyEvents?.items||dashboard.policy.items)[0]?.business_impact||'按适用地区与生效时间核对业务影响' }}</p><footer><span>国内外政策资料库</span><button class="gg-text-btn" @click="emit('navigate','agri-risk')">查看动态<Icon name="arrow" :size="12"/></button></footer></article>
  </div>
  <div class="gg-decision-main-grid"><section class="gg-card gg-decision-market"><div class="gg-card-heading"><div><h2>价格观察与保障位置</h2><p>{{ dashboard.product.contract.toUpperCase() }} · 历史结算价，不代表实时交易报价</p></div><button class="gg-text-btn" @click="emit('navigate','futures')">展开期货看板<Icon name="arrow" :size="14"/></button></div><div v-if="futureError" class="gg-error" role="alert">{{ futureError }}</div><div v-else-if="loadingFutures" class="gg-loading"><span class="gg-spinner"/>读取行情…</div><svg v-else-if="hasPrice" class="gg-decision-price-chart" viewBox="0 0 840 260" role="img" aria-label="玉米指定合约历史结算价与保障价格"><g v-for="n in 5" :key="n"><line x1="58" x2="800" :y1="25+(n-1)*46" :y2="25+(n-1)*46" stroke="#eeeff5"/><text x="48" :y="29+(n-1)*46" text-anchor="end" class="gg-axis">{{ fmt(priceBounds.max-(n-1)*(priceBounds.max-priceBounds.min)/4,0) }}</text></g><line x1="58" x2="800" :y1="y(dashboard.product.guarantee_price)" :y2="y(dashboard.product.guarantee_price)" stroke="#bba270" stroke-dasharray="5 5"/><text x="792" :y="y(dashboard.product.guarantee_price)-8" text-anchor="end" class="gg-guarantee-label">保障价 {{ fmt(dashboard.product.guarantee_price) }}</text><path :d="settlePath" fill="none" stroke="#7076b4" stroke-width="2.6" stroke-linecap="round"/><text v-for="i in [0,Math.floor((history.length-1)/2),history.length-1]" :key="i" :x="x(i)" y="242" text-anchor="middle" class="gg-axis">{{ history[i]?.date }}</text></svg><div v-else class="gg-empty"><strong>本合约暂无可展示行情</strong><span>指定合约缺失时不以其他合约替代。</span></div><div class="gg-decision-chart-foot"><span><i class="gg-dot gg-dot-indigo"/>历史结算价</span><span><i class="gg-guarantee-dot"/>固定产品保障价</span><small>截至 {{ productMarket?.as_of||'—' }} · 非实时</small></div></section>
   <section class="gg-card gg-home-tasks" aria-label="首页待办"><div class="gg-card-heading"><div><h2>业务待办<span class="gg-counter">{{ pendingTasks.length }}</span></h2><p>优先跟进结果待核实、资料缺失与复核事项</p></div><Icon name="clock" :size="20"/></div><div class="gg-task-scope" role="group" aria-label="待办范围"><button :aria-pressed="onlyMyTasks" :class="{active:onlyMyTasks}" @click="onlyMyTasks=true">我的待办</button><button :aria-pressed="!onlyMyTasks" :class="{active:!onlyMyTasks}" @click="onlyMyTasks=false">团队待办</button></div><div v-if="!pendingTasks.length" class="gg-empty gg-small-empty"><Icon name="check" :size="27"/><strong>当前暂无{{ onlyMyTasks?'分配给您的':'未结' }}待办</strong><span>业务状态变化后自动更新。</span></div><button v-for="task in pendingTasks.slice(0,3)" :key="task.id" class="gg-task" @click="emit('task',task)"><span class="gg-task-icon"><Icon :name="task.status==='unknown'?'warning':'file'" :size="17"/></span><div><strong>{{ task.title }}</strong><small>{{ task.description }} · {{ label(task.status) }}</small></div><Icon name="chevron" :size="14"/></button><button class="gg-text-btn gg-full-link" @click="emit('navigate','overview')">查看业务总览与全部待办<Icon name="arrow" :size="14"/></button></section></div>
  <section class="gg-home-shortcuts" aria-label="常用办理入口"><button v-for="entry in shortcuts" :key="entry.page" @click="emit('navigate',entry.page)"><span class="gg-task-icon"><Icon :name="entry.icon" :size="20"/></span><div><strong>{{ entry.label }}<b v-if="entry.count">{{ entry.count }}</b></strong><small>{{ entry.note }}</small></div><Icon name="chevron" :size="14"/></button></section>
  <section class="gg-card"><div class="gg-card-heading"><div><h2>玉米供需快照</h2><p>{{ dashboard.supply_demand.marketing_year }} · 同一发布版本 · {{ label(dashboard.supply_demand.statistic_status) }}</p></div><button class="gg-text-btn" @click="emit('navigate','data')">深入数据与研究<Icon name="arrow" :size="14"/></button></div><div class="gg-supply-metrics"><article v-for="metric in mainSupply" :key="metric.id"><span>{{ metric.name }}</span><strong>{{ metricValue(metric).value }}<small>{{ metricValue(metric).unit }}</small></strong><p v-if="metric.formula">{{ metric.formula }}</p></article></div><div class="gg-decision-source-line"><Icon name="link" :size="14"/><span>来源：中国玉米供需 · 发布 {{ date(dashboard.supply_demand.published_at) }} · 供需、贸易与区域资料按统计期间和发布版本统一管理。</span></div></section>
  <section v-if="latestDecisions.length" class="gg-card"><div class="gg-card-heading"><div><h2>本项目最近业务判断</h2><p>人工意见保留来源版本，投保申请可引用原记录</p></div></div><div v-for="item in latestDecisions" :key="item.id" class="gg-decision-history"><span class="gg-badge" :class="item.disposition==='proceed'?'gg-success':'gg-warning'">{{ label(item.disposition) }}</span><div><strong>{{ item.reason }}</strong><small>{{ item.region }} · {{ date(item.created_at) }} · {{ item.id }}</small></div><button v-if="user.role==='operator'&&item.disposition==='proceed'" class="gg-text-btn" @click="emit('enroll',item)">引用办理<Icon name="arrow" :size="14"/></button></div></section>
 </template>
 <template v-else-if="page==='futures'">
  <section class="gg-card gg-futures-card"><div class="gg-card-heading"><div><span class="gg-overline">FUTURES / HISTORICAL SNAPSHOT</span><h2>玉米期货看板</h2><p>具体合约独立查询，涨跌按上一交易日结算价计算</p></div><label class="gg-futures-select"><span>合约</span><select v-model="ticker" aria-label="选择期货合约" :disabled="loadingFutures" @change="loadFutures(ticker)"><option v-for="choice in futures?.contract_choices || [{ticker:dashboard.market.default_ticker,name:dashboard.market.default_ticker,is_product_contract:true}]" :key="choice.ticker" :value="choice.ticker">{{ choice.name }}{{ choice.is_product_contract?' · 产品指定':'' }}</option></select></label></div><div v-if="futureError" class="gg-error" role="alert"><span>{{ futureError }}</span><button class="gg-text-btn" @click="loadFutures(ticker)">重新加载</button></div><div v-if="loadingFutures" class="gg-loading"><span class="gg-spinner"/>读取具体合约行情…</div><template v-else-if="futures"><div class="gg-futures-summary"><article><span>最新结算价</span><strong>{{ fmt(futures.latest?.settle_price) }}<small>{{ futures.unit }}</small></strong></article><article><span>结算价变动</span><strong :class="Number(futures.latest?.settle_change||0)<0?'gg-market-down':'gg-market-up'">{{ fmt(futures.latest?.settle_change) }}<small>{{ futures.latest?.settle_change_ratio==null?'—':`${fmt(futures.latest.settle_change_ratio*100)}%` }}</small></strong></article><article><span>成交量</span><strong>{{ fmt(futures.latest?.volume,0) }}<small>{{ futures.volume_unit }}</small></strong></article><article><span>持仓量</span><strong>{{ fmt(futures.latest?.open_interest,0) }}<small>{{ futures.volume_unit }}</small></strong></article></div><div class="gg-futures-chart-tools"><div><button :class="{active:chartMode==='candles'}" :disabled="!hasOHLC" @click="chartMode='candles'">K线</button><button :class="{active:chartMode==='settle'}" @click="chartMode='settle'">结算价</button></div><div><button v-for="days in [20,60,120]" :key="days" :class="{active:range===days}" @click="range=days">{{ days }} 交易日</button></div></div><svg v-if="hasPrice" class="gg-futures-chart" viewBox="0 0 840 350" role="img" aria-label="玉米具体合约K线及成交量"><g v-for="n in 5" :key="n"><line x1="58" x2="800" :y1="25+(n-1)*46" :y2="25+(n-1)*46" stroke="#eeeff5"/><text x="48" :y="29+(n-1)*46" text-anchor="end" class="gg-axis">{{ fmt(priceBounds.max-(n-1)*(priceBounds.max-priceBounds.min)/4,0) }}</text></g><g v-if="chartMode==='candles'&&hasOHLC"><g v-for="c in candles" :key="c.row.date" :stroke="Number(c.row.close_price)>=Number(c.row.open_price)?'#b98885':'#74a397'" :fill="Number(c.row.close_price)>=Number(c.row.open_price)?'#b98885':'#74a397'"><title>{{ c.row.date }} 开{{ c.row.open_price }} 高{{ c.row.high_price }} 低{{ c.row.low_price }} 收{{ c.row.close_price }}</title><line :x1="x(c.i)" :x2="x(c.i)" :y1="y(c.row.high_price!)" :y2="y(c.row.low_price!)"/><rect :x="x(c.i)-candleWidth/2" :y="Math.min(y(c.row.open_price!),y(c.row.close_price!))" :width="candleWidth" :height="Math.max(1,Math.abs(y(c.row.open_price!)-y(c.row.close_price!)))"/></g></g><path v-else :d="settlePath" fill="none" stroke="#7278b4" stroke-width="2"/><line x1="58" x2="800" y1="231" y2="231" stroke="#e9ebf2"/><text x="58" y="248" class="gg-axis">成交量（手）</text><g v-for="(row,i) in history" :key="row.date"><rect v-if="row.volume!=null" :x="x(i)-candleWidth/2" :y="volumeY(row.volume)" :width="candleWidth" :height="row.volume/maxVolume*55" fill="#b6bad3"><title>{{ row.date }} 成交{{ fmt(row.volume) }}手 · 持仓{{ fmt(row.open_interest) }}手</title></rect></g><text v-for="i in [0,Math.floor((history.length-1)/2),history.length-1]" :key="i" :x="x(i)" y="331" text-anchor="middle" class="gg-axis">{{ history[i]?.date }}</text></svg><div v-else class="gg-empty"><strong>暂无可绘制行情</strong></div><div class="gg-decision-chart-foot"><span>历史行情截至 {{ futures.as_of }}</span><span>非实时行情 · 缺失不补零</span><button class="gg-text-btn" @click="emit('navigate','arrangements')">进入保险方对冲<Icon name="arrow" :size="14"/></button></div><div v-if="!isProductContract" class="gg-notice"><Icon name="info" :size="16"/><span>当前为对比合约，不能替代本产品 {{ dashboard.product.contract.toUpperCase() }} 的合同采价。</span></div><div v-for="warning in futures.warnings" :key="warning" class="gg-notice"><Icon name="info" :size="16"/><span>{{ warning }}</span></div></template></section>
  <RecordTable v-if="futures" title="逐日行情" :records="futureRecords" :columns="futureColumns" :selectable="false" @export="exportFutures"/>
 </template>
 <template v-else>
  <section class="gg-card gg-agri-intro"><div><span class="gg-overline">REGIONAL INTELLIGENCE</span><h2>区域农情与风险研判</h2><p>结合天气、土壤水分与生育阶段，跟进地块风险和客户服务事项。</p></div><label class="gg-futures-select">监测区域<select v-model="selectedRegion" aria-label="选择农情区域"><option v-for="region in regionObservations" :key="region.region_code" :value="region.region_code">{{ region.region_name }}</option></select></label></section>
  <div v-if="coverageError" class="gg-error" role="alert">{{ coverageError }}</div>
  <div class="gg-kpis gg-weather-kpis"><article><span>日均气温<Icon name="calendar" :size="18"/></span><strong>{{ fmt(currentWeather?.temperature_c) }}<small>℃</small></strong><p>日降水 {{ fmt(currentWeather?.rainfall_mm) }} 毫米</p></article><article><span>区域风速<Icon name="risk" :size="18"/></span><strong>{{ fmt(currentWeather?.wind_speed_ms) }}<small>米/秒</small></strong><p>关注大风与成熟玉米倒伏</p></article><article><span>土壤体积含水量<Icon name="grain" :size="18"/></span><strong>{{ currentWeather?fmt(currentWeather.soil_water_content*100,1):'—' }}<small>%</small></strong><p>观测土层 {{ currentWeather?.soil_depth_cm }} 厘米</p></article><article class="gg-kpi-accent"><span>土壤水分饱和度<Icon name="research" :size="18"/></span><strong>{{ currentWeather?fmt(currentWeather.soil_saturation*100,1):'—' }}<small>%</small></strong><p>{{ currentWeather?.growth_stage_name }} · {{ currentWeather?.observation_date }}</p></article></div>
  <section class="gg-card"><div class="gg-card-heading"><div><h2>天气、土壤与灾害风险</h2><p>{{ currentWeather?.region_name }} · 未来7日 · 评估时间 {{ date(riskItems[0]?.as_of) }}</p></div><span class="gg-chip">{{ riskItems[0]?.model_version }}</span></div><div class="gg-hazard-grid"><article v-for="risk in riskItems" :key="risk.id"><header><strong>{{ risk.hazard_name }}</strong><span class="gg-badge" :class="`gg-${tone(risk.risk_level)}`">{{ label(risk.risk_level) }}</span></header><div class="gg-hazard-value">{{ fmt(risk.probability*100,1) }}<small>%</small></div><div class="gg-hazard-meter"><i :style="{width:`${risk.probability*100}%`}"/></div><p>{{ risk.recommendation }}</p><small>有效至 {{ date(risk.valid_until) }}</small></article></div><div class="gg-note"><Icon name="info" :size="16"/><span>风险研判用于业务服务和人工复核；价格保险仍按保单约定的价格与采价窗口核赔。</span></div></section>
  <section class="gg-card"><div class="gg-card-heading"><div><h2>各产区农情监测</h2><p>按地区查看天气、土壤与作物阶段，点击地区切换风险研判</p></div></div><div class="gg-region-monitor"><button v-for="region in regionObservations" :key="region.region_code" :class="{active:selectedRegion===region.region_code}" @click="selectedRegion=region.region_code"><strong>{{ region.region_name }}</strong><span>{{ fmt(region.temperature_c) }} ℃ · 降水 {{ fmt(region.rainfall_mm) }} 毫米</span><span>土壤饱和度 {{ fmt(region.soil_saturation*100,1) }}%</span><small>{{ region.growth_stage_name }} · {{ region.observation_date }}</small><Icon name="chevron" :size="14"/></button></div></section>
  <section class="gg-card"><div class="gg-card-heading"><div><h2>政策与市场背景</h2><p>按发布时间、生效时间和适用地区核对对投保及风险安排的影响</p></div><div class="gg-policy-filters"><select v-model="policyCategory" aria-label="政策分类"><option value="all">全部分类</option><option value="agriculture">农业支持</option><option value="insurance">保险服务</option><option value="trade">贸易动态</option><option value="market">市场动态</option></select><select v-model="policyCountry" aria-label="政策国家"><option value="all">全部国家</option><option v-for="country in policyCountries" :key="country" :value="country">{{ label(country) }}</option></select></div></div><article v-for="event in policyItems" :key="event.id" class="gg-policy-event"><header><div><span class="gg-badge gg-info">{{ label(event.category) }}</span><span class="gg-chip">{{ label(event.country_code) }}</span></div><time>{{ date(event.published_at) }}</time></header><h3>{{ event.title }}</h3><p>{{ event.summary }}</p><div class="gg-policy-impact"><Icon name="info" :size="15"/><span>业务关注：{{ event.business_impact }}</span></div><footer><span>生效 {{ date(event.effective_at) }} · {{ event.source_name }}</span><button class="gg-text-btn" :aria-expanded="expandedPolicy===event.id" @click="expandedPolicy=expandedPolicy===event.id?'':event.id">{{ expandedPolicy===event.id?'收起详情':'查看详情' }}<Icon name="chevron" :size="13"/></button></footer><div v-if="expandedPolicy===event.id" class="gg-policy-detail"><p>适用范围：{{ label(event.country_code) }} · {{ label(event.category) }}</p><p>{{ event.summary }}</p><p>处理建议：{{ event.business_impact }}</p></div></article><div v-if="!policyItems.length" class="gg-empty gg-small-empty">当前筛选暂无记录</div></section>
 </template>
 <div class="gg-decision-boundary"><Icon name="info" :size="16"/><span>{{ dashboard.notice }}</span><button v-if="user.role==='operator'&&page!=='decision'" class="gg-text-btn" @click="record">记录业务判断<Icon name="arrow" :size="13"/></button></div>
</template>
</template>
